-- SOMENTE LEITURA. Mesma conexao/banco da falha; nao executar CALL ainda.
SELECT DATABASE() AS banco,VERSION() AS mysql,@@SESSION.sql_mode AS modo_sql;
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,EXTRA,GENERATION_EXPRESSION,
 HEX(GENERATION_EXPRESSION) AS expressao_hex,
 REGEXP_LIKE(CONVERT(GENERATION_EXPRESSION USING utf8mb4) COLLATE utf8mb4_bin,CONVERT( USING utf8mb4) COLLATE utf8mb4_bin,'c') AS expressao_compativel_r1
FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='academico_pedidos_ingresso' AND COLUMN_NAME='turma_pendente';
SHOW CREATE TABLE academico_pedidos_ingresso;
SELECT versao,checksum,verificado_em FROM arcadia_schema_migrations WHERE versao IN ('1.1.30','1.1.31');
